from itertools import permutations
from sympy import (Function, nan, S, oo, zoo, I, Float, Rational, Symbol,
                   Piecewise, Add, Mul, Pow, default_sort_key, ordered,
                   sstr, pretty, latex)
f = Function('f')
x = Symbol('x')
values = [nan, S.One, S.Zero, S.NegativeOne, oo, -oo, zoo, I, Float('1.5'), Rational(1, 2), x]
expected = sorted(values, key=default_sort_key)
assert sorted(reversed(values), key=default_sort_key) == expected
for a, b in permutations(values, 2):
    sorted([a, b], key=default_sort_key)
    list(ordered([a, b]))
    for expr in [f(a) + f(b), f(f(a)) + f(f(b)), f(a)*f(b),
                 Add(a, b, evaluate=False), Mul(a, b, evaluate=False),
                 Pow(x, a, evaluate=False) + Pow(x, b, evaluate=False),
                 Piecewise((a, x > 0), (0, True), evaluate=False) +
                 Piecewise((b, x > 0), (0, True), evaluate=False)]:
        for printer in [sstr, pretty, latex]:
            printer(expr)
try:
    nan < S.One
except TypeError:
    pass
else:
    raise AssertionError('NaN comparison should still raise')
print(f(nan) + f(1))
print(list(ordered([nan, S.One])))
print('NaN sorting and printing checks passed')
